INSERT INTO spas_subject(subject_code, subject_name, sort, status, create_by, create_time)
SELECT 'MATH', '数学', 3, '0', 'admin', now()
WHERE NOT EXISTS (SELECT 1 FROM spas_subject WHERE subject_code = 'MATH');

